}

html { font-size: 16px; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  line-height: 1.5;
}

/* ── Skip link ─────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-btn);
  color: var(--color-btn-text);
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
}
.skip-link:focus { top: 1rem; }

/* ── Screen-reader only ────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Site header ───────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.site-header__inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  gap: .6rem;
}
.site-header__logo { font-size: 1.25rem; color: var(--color-btn); }
.site-header__name { font-weight: 700; font-size: 1.05rem; letter-spacing: -.01em; }

/* ── Page layout ───────────────────────────────────────────── */
.page-wrapper {
  max-width: 540px;
  margin: 3rem auto;
  padding: 0 1rem;
}

/* ── Form card ─────────────────────────────────────────────── */
.form-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
}
.form-card__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.02em;
  margin-bottom: .4rem;
}
.form-card__subtitle {
  color: var(--color-text-subtle);
  font-size: .95rem;
  margin-bottom: 1.5rem;
}

/* ── Required legend ───────────────────────────────────────── */
.required-legend {
  font-size: .85rem;
  color: var(--color-text-subtle);
  margin-bottom: 1.75rem;
}
.required-legend span[aria-hidden] {
  color: var(--color-required);
  font-weight: 700;
  margin-right: .2rem;
}

/* ── Form field ────────────────────────────────────────────── */
.form-field { margin-bottom: 1.5rem; }

.form-field__label {
  display: block;
  font-size: .9rem;
  font-weight: 600;
  margin-bottom: .4rem;
  color: var(--color-text);
}
.required-mark {
  color: var(--color-required);
  margin-left: .15rem;
}
.form-field__optional {
  font-weight: 400;
  color: var(--color-text-subtle);
  font-size: .85rem;
  margin-left: .25rem;
}

.form-field__input {
  display: block;
  width: 100%;
  padding: .6rem .8rem;
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  transition: border-color .15s, box-shadow .15s;
  outline: none;
}
.form-field__input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, .25);
}
.form-field__input[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}
.form-field__input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(185, 28, 28, .2);
}

.form-field__help {
  margin-top: .4rem;
  font-size: .82rem;
  color: var(--color-help);
}

.form-field__error {
  margin-top: .4rem;
  font-size: .82rem;
  color: var(--color-error);
  font-weight: 500;
}
.form-field__error[hidden] { display: none; }

/* ── Error summary ─────────────────────────────────────────── */
.error-summary {
  background: var(--color-error-bg);
  border: 1.5px solid var(--color-error-border);
  border-radius: var(--radius-sm);
  padding: 1rem 1.1rem;
  margin-bottom: 1.5rem;
  font-size: .9rem;
  color: var(--color-error);
}
.error-summary[hidden] { display: none; }
.error-summary__title {
  font-weight: 700;
  margin-bottom: .4rem;
}
.error-summary__list {
  list-style: disc;
  padding-left: 1.2rem;
}
.error-summary__list li + li { margin-top: .25rem; }

/* ── Submit button ─────────────────────────────────────────── */
.btn-submit {
  display: block;
  width: 100%;
  padding: .75rem 1rem;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  color: var(--color-btn-text);
  background: var(--color-btn);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background .15s;
  margin-top: .5rem;
}
.btn-submit:hover { background: var(--color-btn-hover); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ── Success panel ─────────────────────────────────────────── */
.success-panel {
  display: flex;
  align-items: flex-start;
  gap: .9rem;
  background: var(--color-success-bg);
  border: 1.5px solid var(--color-success-border);
  border-radius: var(--radius-sm);
  padding: 1.1rem 1.2rem;
  margin-top: 1rem;
}
.success-panel[hidden] { display: none; }
.success-panel__icon {
  font-size: 1.4rem;
  color: var(--color-success-icon);
  line-height: 1;
  flex-shrink: 0;
  margin-top: .1rem;
}
.success-panel__heading {
  font-weight: 700;
  margin-bottom: .2rem;
}
.success-panel__body {
  font-size: .9rem;
  color: var(--color-text-subtle);
}

/* ── Forced colors ─────────────────────────────────────────── */
@media (forced-colors: active) {
  .form-field__input { border: 2px solid ButtonText; }
  .form-field__input:focus { outline: 3px solid Highlight; }
  .btn-submit { forced-color-adjust: none; background: ButtonFace; color: ButtonText; border: 2px solid ButtonText; }
}

/* ── Reduced motion ────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .form-field__input, .btn-submit { transition: none; }
}

/* ── Reflow: narrow viewports ──────────────────────────────── */
@media (max-width: 400px) {
  .form-card { padding: 1.75rem 1.1rem; }
}
