/* ── Skip link ─────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-btn);
  color: var(--color-btn-text);
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
