  padding: 2.5rem 2rem;
}
.form-card__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.02em;
  margin-bottom: .4rem;
}
.form-card__subtitle {
  color: var(--color-text-subtle);
  font-size: .95rem;
  margin-bottom: 1.5rem;
}

