AssistantMessageToolRequest(name='create', tool_call_id='tooluse_a1TZxwebfo9AhqI5eqMTHv', arguments={'file_text': '(function () {
  'use strict';

  const form           = document.getElementById('contact-form');
  const errorSummary   = document.getElementById('form-error-summary');
  const statusRegion   = document.getElementById('form-status');
  const successPanel   = document.getElementById('success-panel');

  // Phone: accept (NXX) NXX-XXXX, NXX-NXX-XXXX, NXXXXXXXXX (10 digits, US)
  const PHONE_RE = /^[\s()*+\-.]?(\(?\d{3}\)?[\s.\-]?\d{3}[\s.\-]?\d{4})$/;

  /**
   * Validate a single field. Returns an error message string or null.
   */
  function validateField(field) {
    if (field.required && !field.value.trim()) {
      if (field.id === 'full-name') return 'Enter your full name.';
      if (field.id === 'email')     return 'Enter a valid email address, e.g. you@example.com.';
    }

    if (field.id === 'email' && field.value.trim()) {
      // Check email format beyond the browser's type="email" heuristic
      if (!field.validity.valid) return 'Enter a valid email address, e.g. you@example.com.';
    }

    if (field.id === 'phone' && field.value.trim()) {
      if (!PHONE_RE.test(field.value.trim())) {
        return 'Enter a valid 10-digit phone number or leave this field empty.';
      }
    }

    return null;
  }

  /**
   * Show or clear the inline error for a field.
   */
  function setFieldError(field, message) {
    const errorEl = document.getElementById(field.id + '-error');
    if (!errorEl) return;

    if (message) {
      errorEl.textContent = 'Error: ' + message;
      errorEl.hidden = false;
      field.setAttribute('aria-invalid', 'true');
    } else {
      errorEl.hidden = true;
      field.removeAttribute('aria-invalid');
    }
  }

  /**
   * Run validation on all fields, render errors, return list of failed fields.
   */
  function validateAll() {
    const fields = [
      document.getElementById('full-name'),
      document.getElementById('email'),
      document.getElementById('phone'),
    ];

    const failures = [];

    fields.forEach(function (field) {
      const msg = validateField(field);
      setFieldError(field, msg);
      if (msg) failures.push({ field, message: msg });
    });

    return failures;
  }

  /**
   * Render the error summary above the form.
   */
  function showErrorSummary(failures) {
    if (!failures.length) {
      errorSummary.hidden = true;
      errorSummary.innerHTML = '';
      return;
    }

    const labelFor = {
      'full-name': 'Full name',
      'email':     'Email address',
      'phone':     'Phone number',
    };

    const title = document.createElement('p');
    title.className = 'error-summary__title';
    title.textContent =
      'There ' + (failures.length === 1 ? 'is 1 error' : 'are ' + failures.length + ' errors') +
      ' in this form. Please correct the following:';

    const list = document.createElement('ul');
    list.className = 'error-summary__list';
    failures.forEach(function ({ field, message }) {
      const li   = document.createElement('li');
      const link = document.createElement('a');
      link.href        = '#' + field.id;
      link.textContent = labelFor[field.id] + ': ' + message;
      li.appendChild(link);
      list.appendChild(li);
    });

    errorSummary.innerHTML = '';
    errorSummary.appendChild(title);
    errorSummary.appendChild(list);
    errorSummary.hidden = false;
  }

  // ── Submit handler ───────────────────────────────────────────
  form.addEventListener('submit', function (event) {
    event.preventDefault();

    const failures = validateAll();

    if (failures.length) {
      showErrorSummary(failures);
      // Move focus to the first invalid field per forms guidance
      failures[0].field.focus();
      return;
    }

    // Clear any previous errors
    errorSummary.hidden = true;
    errorSummary.innerHTML = '';

    // Simulate submission
    form.hidden = true;
    successPanel.hidden = false;
    statusRegion.textContent = 'Message sent. We\'ll get back to you shortly.';
  });

  // ── Live per-field validation (only after first submit attempt) ──
  // We track whether the user has attempted a submit to avoid showing
  // errors on initial render or during casual tabbing.
  let submitted = false;

  form.addEventListener('submit', function () { submitted = true; }, true);

  ['full-name', 'email', 'phone'].forEach(function (id) {
    const field = document.getElementById(id);

    field.addEventListener('blur', function () {
      if (!submitted) return;
      const msg = validateField(field);
      setFieldError(field, msg);
      // Re-build summary silently (don't steal focus)
      const allFailures = validateAll();
      // Restore this field's state since validateAll may have over-written it
      setFieldError(field, msg);
      // Update summary text without moving focus
      showErrorSummary(allFailures);
    });

    field.addEventListener('input', function () {
      if (!submitted) return;
      const msg = validateField(field);
      setFieldError(field, msg);
    });
  });
}());
